/* Past-year questions for Rank mode · JEE Mains · Optics (ray optics and wave optics), grouped by topic and sub-topic.
   Sources: JEE Main, JEE Advanced, IIT-JEE and AIEEE papers. Wording as in the paper; solutions written for this site.
   Fields: y = exam and year, tp = topic, st = sub-topic, q = question, o + c = options and correct index (or array of indices),
   n = numerical answer, s = worked solution, fig = diagram (PhysicaFig spec). M(...) builds a multiple-choice entry, N(...) a numerical one. */
(() => {
'use strict';
const M=(y,tp,st,q,o,c,s,fig)=>({y,tp,st,q,o,c,s,...(fig?{fig}:{})}),N=(y,tp,st,q,n,s,fig)=>({y,tp,st,q,n,s,...(fig?{fig}:{})});
window.PhysicaRankPyqOptics=[
M("JEE Main 2025 · 2 Apr · Shift 2","mirror","Spherical mirror: magnification","Two identical objects are placed in front of convex mirror and concave mirror having same radii of curvature of 12 cm, at same distance of 18 cm from the respective mirrors. The ratio of sizes of the images formed by convex mirror and by concave mirror is",["1/2","2","1/3","3"],0,"f = 6 cm for both. Convex: |m| = {f;|u − f|} = {6;24} = {1;4}. Concave (f = −6, u = −18): |m| = {6;12} = {1;2}.\nRatio = {1/4;1/2} = 1/2."),
M("JEE Main 2025 · 4 Apr · Shift 1","mirror","Spherical mirror: magnification","When an object is placed 40 cm away from a spherical mirror an image of magnification {1;2} is produced. To obtain an image with magnification of {1;3}, the object is to be moved",["80 cm away from the mirror.","20 cm away from the mirror.","20 cm towards the mirror.","40 cm away from the mirror."],3,"Same-sign magnification, reduced and virtual, so it is a convex mirror: m = {f;f − u}.\nu = −40: {f;f + 40} = {1;2} gives f = 40 cm. For m = {1;3}: f + |u| = 3f, |u| = 80 cm.\nThe object moves 40 cm away."),
M("JEE Main 2025 · 4 Apr · Shift 2","mirror","Plane and curved mirror together","A finite size object is placed normal to the principal axis at a distance of 30 cm from a convex mirror of focal length 30 cm. A plane mirror is now placed in such a way that the image produced by both the mirrors coincide with each other. The distance between the two mirrors is",["45 cm","22.5 cm","7.5 cm","15 cm"],2,"Convex mirror: u = −30, f = 30, so v = {uf;u − f} = {−900;−60} = +15 cm (image 15 cm behind it).\nThe plane mirror's image must lie at the same place, so the plane mirror is midway between the object (−30) and the image (+15): at −7.5 cm.\nThe two mirrors are 7.5 cm apart."),
M("JEE Main 2025 · 7 Apr · Shift 2","mirror","Spherical mirror: image position","A mirror is used to produce an image with magnification of 1/4. If the distance between object and its image is 40 cm, then the focal length of the mirror is",["15 cm","10.7 cm","12.7 cm","10 cm"],1,"A magnification of 1/4 with an erect image means a convex mirror: object at u, image at u/4 behind the mirror.\nu + u/4 = 40, so u = 32 cm and v = 8 cm.\n{1;f} = {1;8} − {1;32} = {3;32}, f = 10.7 cm."),
M("JEE Main 2025 · 28 Jan · Shift 2","mirror","Spherical mirror: image position","A concave mirror produces an image of an object such that the distance between the object and image is 20 cm. If the magnification of the image is '−3', then the magnitude of the radius of curvature of the mirror is",["30 cm","7.5 cm","3.75 cm","15 cm"],3,"m = −3 gives v = 3u (both in front). v − u = 20, so u = 10 cm and v = 30 cm.\n{1;f} = {1;10} + {1;30} = {4;30}, f = 7.5 cm, R = 2f = 15 cm."),
M("JEE Main 2024 · 29 Jan · Shift 1","mirror","Spherical mirror: magnification","A convex mirror of radius of curvature 30 cm forms an image that is half the size of the object. The object distance is",["45 cm","−15 cm","−45 cm","15 cm"],1,"f = +15 cm. m = {f;f − u} = {1;2} gives f − u = 30, so u = −15 cm.\nThe object is 15 cm in front of the mirror, which is u = −15 cm in the Cartesian convention."),
M("JEE Main 2024 · 29 Jan · Shift 2","mirror","Spherical mirror: image position","If the distance between object and its two times magnified virtual image produced by a curved mirror is 15 cm, the focal length of the mirror must be",["−10 cm","−12 cm","10/3 cm","15 cm"],0,"A magnified virtual image needs a concave mirror. Object at x in front, image 2x behind the mirror.\nx + 2x = 15 gives x = 5 cm, image distance 10 cm.\n{1;f} = {1;10} − {1;5} = −{1;10}, so f = −10 cm."),
M("JEE Main 2023 · 10 Apr · Shift 1","mirror","Plane mirrors","An object is placed at a distance of 12 cm in front of a plane mirror. The virtual and erect image is formed by the mirror. Now the mirror is moved by 4 cm towards the stationary object. The distance by which the position of image would be shifted, will be",["2 cm towards mirror","4 cm towards mirror","8 cm away from mirror","8 cm towards mirror"],3,"Initially the image is 24 cm from the object. After the move the mirror is 8 cm from the object, so the image is 16 cm from it.\nThe image shifts 8 cm towards the object (the mirror's direction of motion)."),
M("JEE Main 2023 · 11 Apr · Shift 2","mirror","Plane mirrors","When one light ray is reflected from a plane mirror with 30° angle of reflection, the angle of deviation of the ray after reflection is",["130°","120°","110°","140°"],1,"The angle of incidence is 30°. The deviation is 180° − 2i = 180° − 60° = 120°."),
M("JEE Main 2023 · 1 Feb · Shift 2","mirror","Spherical mirror: image position","Two objects A and B are placed at 15 cm and 25 cm from the pole in front of a concave mirror having radius of curvature 40 cm. The distance between images formed by the mirror is",["40 cm","160 cm","60 cm","100 cm"],1,"f = −20 cm. For A (u = −15): {1;v} = −{1;20} + {1;15} = {1;60}, v = +60 cm (virtual).\nFor B (u = −25): {1;v} = −{1;20} + {1;25} = −{1;100}, v = −100 cm (real).\nThe images are on opposite sides of the mirror: 60 + 100 = 160 cm."),
M("JEE Main 2023 · 25 Jan · Shift 2","mirror","Plane mirrors","The light rays from an object have been reflected towards an observer from a standard flat mirror, the image observed by the observer are\nA. Real\nB. Erect\nC. Smaller in size than object\nD. Laterally inverted\nChoose the most appropriate answer from the options given below.",["B and C only","A, C and D only","B and D only","A and D only"],2,"A plane mirror forms a virtual (not real), erect image of the same size as the object, and it is laterally inverted.\nSo only B and D are correct."),
M("JEE Main 2021 · 27 Aug · Shift 1","mirror","Spherical mirror: image position","An object is placed beyond the centre of curvature C of the given concave mirror. If the distance of the object from C is d₁ and the distance of the image formed is d₂ from C, the radius of curvature of this mirror is",["{2d₁d₂;d₁ + d₂}","{2d₁d₂;d₁ − d₂}","{d₁d₂;d₁ + d₂}","{d₁d₂;d₁ − d₂}"],1,"Object distance R + d₁, image distance R − d₂ (the image lies between C and F).\n{1;R + d₁} + {1;R − d₂} = {2;R} gives R(d₁ − d₂) = 2d₁d₂.\nSo R = {2d₁d₂;d₁ − d₂}."),
M("JEE Main 2021 · 24 Feb · Shift 1","mirror","Spherical mirror: image position","The focal length f is related to the radius of curvature r of the spherical convex mirror by",["f = r","f = +{1;2}r","f = −r","f = −{1;2}r"],1,"For a spherical mirror f = {R;2}. In the Cartesian convention a convex mirror has positive R (centre behind the mirror), so f = +r/2."),
M("JEE Main 2021 · 26 Feb · Shift 1","mirror","Spherical mirror: magnification","A short straight object of height 100 cm lies before the central axis of a spherical mirror whose focal length has absolute value |f| = 40 cm. The image of object produced by the mirror is of height 25 cm and has the same orientation of the object. One may conclude from the information:",["Image is virtual, opposite side of convex mirror.","Image is real, same side of concave mirror.","Image is virtual, opposite side of concave mirror.","Image is real, same side of convex mirror."],0,"Same orientation (erect) means the image is virtual, so it lies on the opposite side of the mirror from the object.\nIt is also smaller (m = +1/4), which only a convex mirror gives."),
M("JEE Main 2019 · 9 Apr · Shift 1","mirror","Spherical mirror: magnification","A concave mirror for face viewing has focal length of 0.4 m. The distance at which you hold the mirror from your face in order to see your image upright with a magnification of 5 is",["0.16 m","1.60 m","0.32 m","0.24 m"],2,"f = −0.4 m, m = +5: m = {f;f − u} gives 5(−0.4 − u) = −0.4.\n−2 − 5u = −0.4, so u = −0.32 m. The mirror is held 0.32 m from the face."),
M("JEE Main 2019 · 9 Jan · Shift 2","mirror","Plane mirrors","Two plane mirrors are inclined to each other such that a ray of light incident on the first mirror M₁ and parallel to the second mirror M₂ is finally reflected from the second mirror M₂ parallel to the first mirror (M₁). The angle between the two mirrors will be",["75°","90°","60°","45°"],2,"Let M₁ lie along angle 0 and M₂ along angle θ. The incident ray (parallel to M₂) has direction θ.\nReflection in M₁ gives −θ. Reflection in M₂ gives 2θ − (−θ) = 3θ.\nThis must be parallel to M₁: 3θ = 180°, θ = 60°."),
M("JEE Main 2019 · 12 Jan · Shift 1","mirror","Plane mirrors","A point source of light S is placed at a distance L in front of the centre of a plane mirror of width d which is hanging vertically on a wall. A man walks in front of the mirror along a line parallel to the mirror, at a distance 2L from it. The distance over which the man can see the image of the light source in the mirror is",["3d","2d","d","{d;2}"],0,"The image is L behind the mirror. The man sees it only inside the cone from the image through the mirror's edges.\nAt the man's distance (2L in front, so 3L from the image) the cone has width d × {3L;L} = 3d."),
M("JEE Main 2018 · Online","mirror","Spherical mirror: image position","A particle is oscillating on the x-axis with an amplitude 2 cm about the point x₀ = 10 cm, with a frequency ω. A concave mirror of focal length 5 cm is placed at the origin (x = 0, facing the particle). Identify the correct statements.\n(1) The image executes periodic motion.\n(2) The image executes non-periodic motion.\n(3) The turning points of the image are asymmetric w.r.t. the image of the point at x = 10 cm.\n(4) The distance between the turning points of the oscillation of the image is {100;21} cm.",["2, 4","2, 3","1, 3, 4","1, 4"],2,"Object distance oscillates between 8 cm and 12 cm. Image distance v = {uf;u − f}: 13.33 cm at u = 8, 10 cm at u = 10, 8.57 cm at u = 12.\nThe image repeats with the object (periodic, not simple harmonic). The turning points are 3.33 cm above and 1.43 cm below 10 cm: asymmetric.\nSeparation 13.33 − 8.57 = 4.76 = {100;21} cm. So (1), (3), (4)."),
M("JEE Main 2015 · Online","mirror","Spherical mirror: magnification","You are asked to design a shaving mirror assuming that a person keeps it 10 cm from his face and views the magnified image of the face at the closest comfortable distance of 25 cm. The radius of curvature of the mirror would then be",["30 cm","24 cm","60 cm","−24 cm"],2,"The image is 25 cm from the eye (the face), which is 10 cm from the mirror, so v = +15 cm behind the mirror; u = −10 cm.\n{1;f} = {1;15} − {1;10} = −{1;30}: f = −30 cm (concave).\nThe radius of curvature has magnitude 60 cm."),
M("JEE Advanced 2013","mirror","Plane mirrors","A ray of light travelling in the direction {1;2}(î + √3 ĵ) is incident on a plane mirror. After reflection, it travels along the direction {1;2}(î − √3 ĵ). The angle of incidence is",["30°","45°","60°","75°"],0,"Only the ĵ component reverses, so the mirror's normal is along ĵ.\ncos i = (î + √3 ĵ)/2 · ĵ = {√3;2}, so the angle of incidence i = 30°."),
M("AIEEE 2011","mirror","Moving object and image","A car is fitted with a convex side-view mirror of focal length 20 cm. A second car 2.8 m behind the first car is overtaking the first car at a relative speed of 15 m s⁻¹. The speed of the image of the second car as seen in the mirror of the first one is",["{1;10} m s⁻¹","{1;15} m s⁻¹","10 m s⁻¹","15 m s⁻¹"],1,"Image speed = m² × object speed, with m = {f;f + u} = {0.2;3.0} = {1;15}.\nSpeed = {1;225} × 15 = {1;15} m s⁻¹."),
M("IIT-JEE 2007","mirror","Spherical mirror: image position","In an experiment to determine the focal length (f) of a concave mirror by the u-v method, a student places the object pin A on the principal axis at a distance x from the pole P. The student looks at the pin and its inverted image from a distance keeping his/her eye in line with PA. When the student shifts his/her eye towards left, the image appears to the right of the object pin. Then,",["x < f","f < x < 2f","x = 2f","x > 2f"],1,"By parallax, the nearer object appears to move opposite to the eye. The image appearing to the right means the image is nearer to the eye than the pin, that is, farther from the mirror: v > x.\nFor a real image, v > x holds only when f < x < 2f (v = x at 2f)."),
M("AIEEE 2003","mirror","Plane mirrors","To get three images of a single object, one should have two plane mirrors at an angle of",["60°","90°","120°","30°"],1,"Number of images = {360°;θ} − 1 = 3 gives θ = 90°."),
M("AIEEE 2002","mirror","Plane mirrors","If two mirrors are kept at 60° to each other, then the number of images formed by them is",["5","6","7","8"],0,"{360°;60°} − 1 = 6 − 1 = 5 images."),
M("IIT-JEE 2002","mirror","Plane mirrors","Two plane mirrors A and B are aligned parallel to each other, 0.2 m apart and each 2√3 m long. A light ray is incident at an angle of 30° (to the normal) at a point just inside one end of A. The plane of incidence coincides with the plane of the figure. The maximum number of times the ray undergoes reflections (including the first one) before it emerges out is",["28","30","32","34"],1,"Between successive reflections the ray advances along the mirrors by 0.2 tan 30° = {0.2;√3} m.\nNumber of such steps in the length: {2√3;0.2/√3} = 30. The first reflection is at the start, and the last one possible is the 30th."),
M("IIT-JEE 2000","mirror","Plane mirrors","A point source of light B is placed at a distance L in front of the centre of a mirror of width d hung vertically on a wall. A man walks in front of the mirror along a line parallel to the mirror at a distance 2L from it. The greatest distance over which he can see the image of the light source in the mirror is",["d/2","d","2d","3d"],3,"The image is L behind the mirror, the man is 3L from the image. The mirror edges limit the visible region to a width d × {3L;L} = 3d."),
M("IIT-JEE 1998","mirror","Mirror and water","A concave mirror is placed on a horizontal table, with its axis directed vertically upwards. Let O be the pole of the mirror and C its centre of curvature. A point object is placed at C. It has a real image, also located at C. If the mirror is now filled with water, the image will be",["real, and will remain at C.","real, and located at a point between C and ∞.","virtual, and located at a point between C and O.","real, and located at a point between C and O."],3,"For rays near the axis, water makes the object (seen from inside the water) appear at n × R = 1.33R from the mirror.\n{1;v} = {2;R} − {1;1.33R} = {1.25;R}, so v = 0.8R in the water, a real image; seen from air it is at 0.8R/n = 0.6R.\nThe image is real and between C and O."),
M("IIT-JEE 1988","mirror","Spherical mirror: magnification","A short linear object of length b lies along the axis of a concave mirror of focal length f at a distance u from the pole of the mirror. The size of the image is approximately equal to",["b·√({u − f;f})","b·√({f;u − f})","b·{u − f;f}","b·({f;u − f})²"],3,"For a small length along the axis, dv = −m² du with m = {f;f − u}.\nSo the image length is b m² = b({f;u − f})²."),
N("JEE Main 2025 · 4 Apr · Shift 1","mirror","Spherical mirror: image position","Distance between object and its image (magnified by −{1;3}) is 30 cm. The focal length of the mirror used is ({x;4}) cm, where magnitude of value of x is ______.",45,"m = −{1;3} means a real image at v = u/3 on the same side. u − u/3 = 30 gives u = 45 cm, v = 15 cm.\n{1;f} = {1;45} + {1;15} = {4;45}, f = {45;4} cm, so x = 45."),
N("JEE Main 2025 · 22 Jan · Shift 1","mirror","Moving object and image","The driver sitting in a parked car is watching vehicles approaching from behind with the help of his side view mirror, which is a convex mirror with radius of curvature R = 2 m. Another car approaches him from behind with a uniform speed of 90 km/hr. When the car is at a distance of 24 m from him, the magnitude of the acceleration of the car in the side view mirror is 'a'. The value of 100a is ______ m/s².",8,"f = 1 m, u = 24 m, speed 25 m/s. Image speed v′ = ({f;u + f})² u′, so a = {2f²u′²;(u + f)³}.\na = {2 × 625;25³} = 0.08 m/s², so 100a = 8."),
N("JEE Main 2023 · 6 Apr · Shift 1","mirror","Plane mirrors","Two vertical parallel mirrors A and B are separated by 10 cm. A point object O is placed at a distance of 2 cm from mirror A. The distance of the second nearest image behind mirror A from the mirror A is ______ cm.",18,"Measure x from A, with B at x = 10 and O at x = 2. Images lie at x = 2 + 20k and x = −2 + 20k.\nBehind A (x < 0): −2, −18, −22, … The second nearest is at 18 cm."),
N("JEE Main 2023 · 1 Feb · Shift 1","mirror","Spherical mirror: image position","A thin cylindrical rod of length 10 cm is placed horizontally on the principal axis of a concave mirror of focal length 20 cm. The rod is placed in such a way that mid point of the rod is at 40 cm from the pole of the mirror. The length of the image formed by the mirror will be {x;3} cm. The value of x is ______.",32,"The ends are at u = 35 cm and 45 cm. v = {uf;u − f}: 46.67 cm and 36 cm.\nImage length = 46.67 − 36 = {32;3} cm, so x = 32."),
N("JEE Main 2022 · 28 Jul · Shift 2","mirror","Spherical mirror: image position","An object 'O' is placed at a distance of 100 cm in front of a concave mirror of radius of curvature 200 cm. The object starts moving towards the mirror at a speed 2 cm/s. The position of the image from the mirror after 10 s will be at ______ cm.",400,"f = 100 cm, so the object starts at the focus. After 10 s it is 80 cm away (inside the focus).\n{1;v} = {1;f} − {1;u} in magnitudes gives {1;v} = {1;80} − {1;100} = {1;400}.\nThe virtual image is 400 cm behind the mirror."),
N("JEE Main 2022 · 26 Jun · Shift 1","mirror","Plane mirrors","A light ray is incident, at an incident angle θ₁, on the system of two plane mirrors M₁ and M₂ having an inclination angle 75° between them. After reflecting from mirror M₁ it gets reflected back by the mirror M₂ with an angle of reflection 30°. The total deviation of the ray will be ______ degree.",210,"Two reflections give a total deviation of 360° − 2 × (angle between the mirrors) = 360° − 150° = 210°, whatever the angle of incidence.\n(Check: the triangle of mirrors and ray gives θ₁ = 45°; (180° − 90°) + (180° − 60°) = 210°.)"),
N("JEE Advanced 2022","mirror","Moving object and image","An object and a concave mirror of focal length f = 10 cm both move along the principal axis of the mirror with constant speeds. The object moves with speed V₀ = 15 cm s⁻¹ towards the mirror with respect to a laboratory frame. The distance between the object and the mirror at a given moment is denoted by u. When u = 30 cm, the speed of mirror Vₘ is such that the image is instantaneously at rest with respect to the laboratory frame, and the object forms a real image. The magnitude of Vₘ is ______ cm s⁻¹.",3,"For u = 30, f = 10: v = 15 cm, so (v/u)² = {1;4}.\nTake the direction from the mirror towards the object as positive, and let the mirror move away from the object at W. Then u changes at the rate W − 15 and v at −({v;u})²(W − 15) = −{W − 15;4}.\nThe image position is (mirror position + v), so its velocity is −W − {W − 15;4} = 0, giving W = 3 cm s⁻¹.\nSo Vₘ = 3 cm s⁻¹, directed away from the object."),
N("JEE Main 2021 · 26 Feb · Shift 2","mirror","Plane mirrors","A point source of light S, placed at a distance 60 cm in front of the centre of a plane mirror of width 50 cm, hangs vertically on a wall. A man walks in front of the mirror along a line parallel to the mirror at a distance 1.2 m from it. The distance between the extreme points where he can see the image of the light source in the mirror is ______ cm.",150,"The image is 60 cm behind the mirror; the man is 120 + 60 = 180 cm from the image.\nHe sees it between the lines from the image through the mirror's edges: width 50 × {180;60} = 150 cm."),
N("JEE Main 2020 · 3 Sep · Shift 2","mirror","Moving object and image","When an object is kept at a distance of 30 cm from a concave mirror, the image is formed at a distance of 10 cm from the mirror. If the object is moved with a speed of 9 cm s⁻¹, the speed (in cm s⁻¹) with which image moves at that instant is ______.",1,"The image speed is ({v;u})² times the object speed: ({10;30})² × 9 = 1 cm s⁻¹."),
N("IIT-JEE 2010","mirror","Moving object and image","Image of an object approaching a convex mirror of radius of curvature 20 m along its optical axis is observed to move from {25;3} m to {50;7} m in 30 seconds. What is the speed of the object in km per hour?",3,"f = 10 m. From {1;u} = {1;f} − {1;v}: v = {25;3} gives u = −50 m; v = {50;7} gives u = −25 m.\nThe object moves 25 m in 30 s: {25;30} m/s = 3 km/h."),
M("IIT-JEE 2007","mirror","Spherical mirror: image position","Each question contains Statement-1 (assertion) and Statement-2 (reason). Of these statements, mark the correct choice.\nStatement-1: The formula connecting u, v and f for a spherical mirror is valid only for mirrors whose sizes are very small compared to their radii of curvature.\nStatement-2: Laws of reflection are strictly valid for plane surfaces, but not for large spherical surfaces.",["Statements 1 and 2 are true and statement-2 is a correct explanation for statement-1","Statements 1 and 2 are true and statement-2 is not a correct explanation for statement-1","Statement-1 is true, statement-2 is false","Statement-1 is false, statement-2 is true"],2,"The mirror formula needs paraxial rays (a small aperture), so statement 1 is true.\nThe laws of reflection hold at every point of any surface, large or small, so statement 2 is false."),
N("IIT-JEE 1991","mirror","Spherical mirror: image position","A thin rod of length {f;3} is placed along the optic axis of a concave mirror of focal length f such that its image, which is real and elongated, just touches the rod. The magnification is ______.",1.5,"The image touches the rod only at the end whose image coincides with itself: the end at 2f. The rod therefore runs from {5f;3} to 2f.\nThe end at {5f;3} has v = {uf;u − f} = 2.5f. The image runs from 2f to 2.5f: length 0.5f.\nMagnification = {0.5f;f/3} = 1.5."),
M("JEE Main 2025 · 2 Apr · Shift 1","refr","Refraction at a spherical surface","A spherical surface separates two media of refractive indices 1 and 1.5 as shown in the figure (n₁ = 1 on the left, n₂ = 1.5 on the right; the surface is convex towards the object, its radius R = 0.4 m, its centre of curvature C lies in medium 2). The object O is 0.2 m from the surface in medium 1. Distance of the image of the object 'O' is",["0.24 m right to the spherical surface","0.4 m left to the spherical surface","0.4 m right to the spherical surface","0.24 m left to the spherical surface"],1,"{n₂;v} − {n₁;u} = {n₂ − n₁;R} with u = −0.2, R = +0.4:\n{1.5;v} = {0.5;0.4} − {1;0.2} = 1.25 − 5 = −3.75, so v = −0.4 m.\nThe image is virtual, 0.4 m to the left of the surface."),
M("JEE Main 2025 · 3 Apr · Shift 2","refr","Refractive index, speed and wavelength","A monochromatic light of frequency 5 × 10¹⁴ Hz travelling through air, is incident on a medium of refractive index '2'. Wavelength of the refracted light will be",["400 nm","300 nm","500 nm","600 nm"],1,"The frequency stays 5 × 10¹⁴ Hz; the speed becomes c/2.\nλ = {c;nf} = {3 × 10⁸;2 × 5 × 10¹⁴} = 300 nm."),
M("JEE Main 2025 · 7 Apr · Shift 2","refr","Total internal reflection","A transparent block A having refractive index μ = 1.25 is surrounded by another medium of refractive index μ = 1.0. A light ray is incident on the flat face of the block with incident angle θ. The top surface of the block is perpendicular to this flat face. What is the maximum value of θ for which light suffers total internal reflection at the top surface of the block?",["tan⁻¹({3;4})","tan⁻¹({4;3})","cos⁻¹({3;4})","sin⁻¹({3;4})"],3,"At the top surface TIR needs incidence ≥ θc, where sin θc = {1;1.25} = 0.8.\nIf r is the refraction angle at the first face, the incidence at the top is 90° − r, so cos r ≥ 0.8, i.e. sin r ≤ 0.6.\nsin θ = 1.25 sin r ≤ 0.75, so θmax = sin⁻¹({3;4})."),
M("JEE Main 2025 · 23 Jan · Shift 1","refr","Refraction at a spherical surface","A spherical surface of radius of curvature R, separates air from glass (refractive index = 1.5). The centre of curvature is in the glass medium. A point object 'O' is placed in air on the optic axis of the surface, so that its real image is formed at 'I' inside glass. The line OI intersects the spherical surface at P and PO = PI. The distance PO equals to",["3R","1.5R","2R","5R"],3,"Let PO = PI = x. {n₂;v} − {n₁;u} = {n₂ − n₁;R}: {1.5;x} + {1;x} = {0.5;R}.\n{2.5;x} = {0.5;R}, so x = 5R."),
M("JEE Main 2025 · 23 Jan · Shift 1","refr","Lateral shift in a slab","What is the lateral shift of a ray refracted through a parallel-sided glass slab of thickness 'h' in terms of the angle of incidence 'i' and angle of refraction 'r', if the glass slab is placed in air medium?",["{h cos(i − r);sin r}","h","{h tan(i − r);tan r}","{h sin(i − r);cos r}"],3,"The ray travels a length {h;cos r} inside the slab. Its lateral shift is that length times sin(i − r).\nShift = {h sin(i − r);cos r}."),
M("JEE Main 2025 · 23 Jan · Shift 2","mirror","Mirror in a liquid","A concave mirror of focal length f in air is dipped in a liquid of refractive index μ. Its focal length in the liquid will be",["{f;μ}","{f;(μ − 1)}","f","μf"],2,"A mirror works only by reflection (f = R/2), so its focal length does not depend on the medium. It stays f."),
M("JEE Main 2025 · 28 Jan · Shift 1","refr","Total internal reflection","A hemispherical vessel is completely filled with a liquid of refractive index μ. A small coin is kept at the lowest point (O) of the vessel as shown in figure. The minimum value of the refractive index of the liquid so that a person can see the coin from point E (at the level of the vessel) is",["√3","{3;2}","√2","{√3;2}"],2,"The most oblique ray from O meets the flat liquid surface at the rim: tan i = R/R, so i = 45°.\nTo reach an eye at the level of the surface the ray must leave almost along the surface: μ sin i = 1.\nμ = {1;sin 45°} = √2."),
M("JEE Main 2025 · 28 Jan · Shift 2","refr","Refraction at a spherical surface","In a long glass tube, mixture of two liquids A and B with refractive indices 1.3 and 1.4 respectively, forms a convex meniscus towards A. If an object placed at 13 cm from the vertex of the meniscus in A forms an image with magnification of '−2' then the radius of curvature of meniscus is",["{1;3} cm","1 cm","{4;3} cm","{2;3} cm"],3,"m = {n₁v;n₂u} = −2 with u = −13: v = {(−2)(1.4)(−13);1.3} = 28 cm.\n{n₂;v} − {n₁;u} = {n₂ − n₁;R}: {1.4;28} + {1.3;13} = 0.15 = {0.1;R}.\nR = {2;3} cm."),
M("JEE Main 2024 · 8 Apr · Shift 1","refr","Total internal reflection","Critical angle of incidence for a pair of optical media is 45°. The refractive indices of first and second media are in the ratio",["1 : 2","1 : √2","√2 : 1","2 : 1"],2,"sin θc = {n₂;n₁} = sin 45° = {1;√2}, so n₁ : n₂ = √2 : 1."),
M("JEE Main 2023 · 6 Apr · Shift 1","refr","Refractive index, speed and wavelength","A monochromatic light wave with wavelength λ₁ and frequency υ₁ in air enters another medium. If the angle of incidence and angle of refraction at the interface are 45° and 30° respectively, then the wavelength λ₂ and frequency υ₂ of the refracted wave are",["λ₂ = √2 λ₁, υ₂ = υ₁","λ₂ = {1;√2} λ₁, υ₂ = υ₁","λ₂ = λ₁, υ₂ = √2 υ₁","λ₂ = λ₁, υ₂ = {1;√2} υ₁"],1,"Frequency never changes on refraction: υ₂ = υ₁.\nn = {sin 45°;sin 30°} = √2, and λ₂ = {λ₁;n} = {λ₁;√2}."),
M("JEE Main 2023 · 11 Apr · Shift 1","refr","Total internal reflection","The critical angle for a denser-rarer interface is 45°. The speed of light in rarer medium is 3 × 10⁸ m/s. The speed of light in the denser medium is",["5 × 10⁷ m/s","2.12 × 10⁸ m/s","3.12 × 10⁷ m/s","√2 × 10⁸ m/s"],1,"sin θc = {v₁;v₂} (denser/rarer): v(denser) = 3 × 10⁸ × sin 45° = {3 × 10⁸;√2}.\nThis is 2.12 × 10⁸ m/s."),
M("JEE Main 2023 · 12 Apr · Shift 1","refr","Apparent depth","An ice cube has a bubble inside. When viewed from one side the apparent distance of the bubble is 12 cm. When viewed from the opposite side, the apparent distance of the bubble is observed as 4 cm. If the side of the ice cube is 24 cm, the refractive index of the ice cube is",["{4;3}","{6;5}","{2;3}","{3;2}"],3,"Let the bubble be x from one face: {x;n} = 12 and {24 − x;n} = 4.\nAdding: {24;n} = 16, so n = 1.5."),
M("JEE Main 2023 · 13 Apr · Shift 1","refr","Apparent depth","A vessel of depth 'd' is half filled with oil of refractive index n₁ and the other half is filled with water of refractive index n₂. The apparent depth of this vessel when viewed from above will be",["{d(n₁ + n₂);2n₁n₂}","{dn₁n₂;(n₁ + n₂)}","{dn₁n₂;2(n₁ + n₂)}","{2d(n₁ + n₂);n₁n₂}"],0,"Apparent depth = Σ {real depth;n} = {d/2;n₁} + {d/2;n₂} = {d(n₁ + n₂);2n₁n₂}."),
N("JEE Main 2023 · 31 Jan · Shift 2","refr","Apparent depth","A microscope is focused on an object at the bottom of a bucket. If liquid with refractive index {5;3} is poured inside the bucket, then microscope have to be raised by 30 cm to focus the object again. The height of the liquid in the bucket is ______ cm.",75,"The object appears raised by h(1 − {1;n}) = h(1 − {3;5}) = 0.4h.\nThe microscope must be raised by this amount: 0.4h = 30, so h = 75 cm."),
M("JEE Main 2022 · 25 Jul · Shift 1","prism","Rainbow and natural phenomena","Which of the following statement is correct?",["In primary rainbow, observer sees red colour on the top and violet on the bottom.","In primary rainbow, observer sees violet colour on the top and red on the bottom.","In primary rainbow, light waves suffer total internal reflection twice before coming out of water drops.","Primary rainbow is less bright than secondary rainbow."],0,"In the primary bow, red light is deviated least and reaches the eye from the drops higher in the sky, so red is on the outside (top) and violet inside (bottom).\nThe primary bow has one internal reflection and is brighter than the secondary."),
M("JEE Main 2022 · 25 Jul · Shift 1","refr","Refractive index, speed and wavelength","Time taken by light to travel in two different materials A and B of refractive indices μ_A and μ_B of same thickness is t₁ and t₂ respectively. If t₂ − t₁ = 5 × 10⁻¹⁰ s and the ratio of μ_A to μ_B is 1 : 2. Then, the thickness of material, in metre is (Given v_A and v_B are velocities of light in A and B materials respectively.)",["5 × 10⁻¹⁰ v_A m","5 × 10⁻¹⁰ m","1.5 × 10⁻¹⁰ m","5 × 10⁻¹⁰ v_B m"],0,"v_B = {v_A;2}. With thickness d: t₂ − t₁ = {d;v_B} − {d;v_A} = {2d;v_A} − {d;v_A} = {d;v_A}.\nSo d = 5 × 10⁻¹⁰ v_A metre."),
M("JEE Main 2022 · 26 Jul · Shift 2","refr","Total internal reflection","Light travels in two media M₁ and M₂ with speeds 1.5 × 10⁸ m s⁻¹ and 2.0 × 10⁸ m s⁻¹ respectively. The critical angle between them is",["tan⁻¹({3;√7})","tan⁻¹({2;3})","cos⁻¹({3;4})","sin⁻¹({2;3})"],0,"Light goes from the slower medium M₁ to the faster M₂: sin θc = {1.5;2.0} = {3;4}.\nThen cos θc = {√7;4} and tan θc = {3;√7}."),
M("JEE Main 2022 · 29 Jul · Shift 2","refr","Snell's law","Light enters from air into a given medium at an angle of 45° with interface of the air-medium surface. After refraction, the light ray is deviated through an angle of 15° from its original direction. The refractive index of the medium is",["1.732","1.333","1.414","2.732"],2,"The incidence angle is 45°. The deviation is i − r = 15°, so r = 30°.\nn = {sin 45°;sin 30°} = √2 = 1.414."),
M("JEE Main 2022 · 25 Jun · Shift 1","refr","Total internal reflection","A light wave travelling linearly in a medium of dielectric constant 4, incidents on the horizontal interface separating medium with air. The angle of incidence for which the total intensity of incident wave will be reflected back into the same medium will be (Given: relative permeability of medium μᵣ = 1)",["10°","20°","30°","60°"],3,"n = √(εᵣμᵣ) = 2, so the critical angle is sin⁻¹({1;2}) = 30°.\nTotal reflection needs an incidence angle above 30°; of the options only 60° does."),
M("JEE Main 2022 · 25 Jun · Shift 1","refr","Refractive index, speed and wavelength","The difference of speed of light in the two media A and B, (v_A − v_B) is 2.6 × 10⁷ m/s. If the refractive index of medium B is 1.47, then the ratio of refractive index of medium B to medium A is (Given: speed of light in vacuum c = 3 × 10⁸ m s⁻¹)",["1.303","1.318","1.13","0.12"],2,"v_B = {3 × 10⁸;1.47} = 2.04 × 10⁸ m/s, so v_A = 2.04 × 10⁸ + 0.26 × 10⁸ = 2.30 × 10⁸ m/s.\n{n_B;n_A} = {v_A;v_B} = {2.30;2.04} ≈ 1.13."),
M("JEE Main 2022 · 27 Jun · Shift 1","refr","Snell's law","Consider a light travelling in air is incident into a medium of refractive index √(2n). The incident angle is twice that of refracting angle. Then, the angle of incidence will be",["sin⁻¹(√n)","cos⁻¹(√({n;2}))","sin⁻¹(√(2n))","2cos⁻¹(√({n;2}))"],3,"With i = 2r: {sin 2r;sin r} = 2 cos r = √(2n), so cos r = √({n;2}).\nThe angle of incidence is i = 2r = 2cos⁻¹(√({n;2}))."),
M("JEE Main 2022 · 27 Jun · Shift 2","huyg","Frequency, speed and wavelength","If a wave gets refracted into a denser medium, then which of the following is true?",["wavelength, speed and frequency decreases.","wavelength increases, speed decreases and frequency remains constant.","wavelength and speed decreases but frequency remains constant.","wavelength, speed and frequency increases."],2,"Frequency is fixed by the source. In the denser medium v = c/n is smaller, and λ = v/f is smaller too."),
M("JEE Main 2022 · 29 Jun · Shift 2","refr","Total internal reflection","The speed of light in media 'A' and 'B' are 2.0 × 10¹⁰ cm/s and 1.5 × 10¹⁰ cm/s respectively. A ray of light enters from the medium B to A at an incident angle 'θ'. If the ray suffers total internal reflection, then",["θ = sin⁻¹({3;4})","θ > sin⁻¹({2;3})","θ < sin⁻¹({3;4})","θ > sin⁻¹({3;4})"],3,"B (slower) is the denser medium. sin θc = {n_A;n_B} = {v_B;v_A} = {1.5;2.0} = {3;4}.\nTIR happens when θ > θc = sin⁻¹({3;4})."),
M("JEE Main 2021 · 1 Sep · Shift 2","refr","Apparent depth","A glass tumbler having inner depth of 17.5 cm is kept on a table. A student starts pouring water (μ = {4;3}) into it while looking at the surface of water from the above. When he feels that the tumbler is half filled, he stops pouring water. Up to what height, the tumbler is actually filled?",["10 cm","11.7 cm","7.5 cm","8.75 cm"],0,"If the water height is h, the water layer appears {h;n} = 0.75h deep. The tumbler looks half filled when the air gap above it equals this apparent depth.\n17.5 − h = 0.75h, so h = 10 cm."),
M("JEE Main 2021 · 22 Jul · Shift 2","refr","Total internal reflection","A ray of light passes from a denser medium to a rarer medium at an angle of incidence i. The reflected and refracted rays make an angle of 90° with each other. The angles of reflection and refraction are respectively r and r′. The critical angle is given by",["sin⁻¹(tan r′)","tan⁻¹(sin i)","sin⁻¹(tan r)","sin⁻¹(cot i)"],2,"Reflection gives r = i, and the 90° condition gives r + r′ = 90°.\nSnell's law: n sin i = sin r′ = cos i, so {1;n} = tan i = tan r.\nsin θc = {1;n} = tan r."),
M("JEE Main 2021 · 25 Jul · Shift 1","refr","Total internal reflection","A ray of laser of a wavelength 630 nm is incident at an angle of 30° at the diamond-air interface. It is going from diamond to air. The refractive index of diamond is 2.42 and that of air is 1. Choose the correct option.",["angle of refraction is 53.4°","angle of refraction is 24.41°","angle of refraction is 30°","refraction is not possible."],3,"sin θc = {1;2.42} = 0.413, so θc ≈ 24.4°.\nThe incidence angle 30° is larger than θc, so the ray is totally reflected and refraction is not possible."),
M("JEE Main 2021 · 25 Jul · Shift 2","refr","Total internal reflection","A ray of light entering from air into a denser medium of refractive index {4;3}, as shown in figure (the ray enters through one face at angle θ and then meets the adjacent face, which is perpendicular to the first). The light ray suffers total internal reflection at the adjacent surface as shown. The maximum value of angle θ should be equal to",["sin⁻¹({√7;4})","sin⁻¹({√7;3})","sin⁻¹({√5;3})","sin⁻¹({√5;4})"],1,"sin θc = {3;4} at the adjacent face. If r is the refraction angle at the first face, the incidence at the second face is 90° − r, so cos r ≥ {3;4} and sin r ≤ {√7;4}.\nsin θ = {4;3} sin r ≤ {√7;3}, so θmax = sin⁻¹({√7;3})."),
M("JEE Main 2020 · 8 Jan · Shift 2","refr","Total internal reflection","The critical angle of a medium for a specific wavelength, if the medium has relative permittivity 3 and relative permeability {4;3} for this wavelength, will be",["15°","30°","45°","60°"],1,"n = √(εᵣμᵣ) = √(3 × {4;3}) = 2.\nsin θc = {1;2}, so θc = 30°."),
M("JEE Main 2020 · 9 Jan · Shift 1","refr","Apparent depth","A vessel of depth 2h is half filled with a liquid of refractive index 2√2 and the upper half with another liquid of refractive index √2. The liquids are immiscible. The apparent depth of the inner surface of the bottom of vessel will be",["{h;√2}","{3;4}h√2","{h;3√2}","{h;2(√2 + 1)}"],1,"Apparent depth = Σ {depth;n} = {h;√2} + {h;2√2} = {3h;2√2} = {3;4}h√2."),
M("JEE Main 2020 · 9 Jan · Shift 2","refr","Total internal reflection","There is a small source of light at some depth below the surface of water (refractive index = {4;3}) in a tank of large cross sectional surface area. Neglecting any reflection from the bottom and absorption by water, percentage of light that emerges out of surface is (nearly) [Use the fact that surface area of a spherical cap of height h and radius of curvature r is 2πrh]",["34%","17%","21%","50%"],1,"Light escapes only inside the cone of half-angle θc, with sin θc = {3;4}, cos θc = {√7;4} = 0.661.\nThe fraction of all directions is {2πr²(1 − cos θc);4πr²} = {1 − 0.661;2} ≈ 0.17, about 17%."),
M("JEE Main 2019 · 10 Apr · Shift 1","huyg","Optical path","A ray of light AO in vacuum is incident on a glass slab at angle 60° and refracted at angle 30° along OB as shown in figure (A is at perpendicular distance a above the surface and B is at perpendicular distance b below it). The optical path length of light ray from A to B is",["2a + {2b;3}","2a + 2b","{2√3;a} + 2b","2a + {2b;√3}"],1,"n = {sin 60°;sin 30°} = √3. In vacuum AO = {a;cos 60°} = 2a.\nIn glass OB = {b;cos 30°} = {2b;√3}, and the optical path is n × OB = 2b.\nTotal = 2a + 2b."),
M("JEE Main 2019 · 12 Apr · Shift 1","mirror","Mirror and water","A concave mirror has radius of curvature of 40 cm. It is at the bottom of a glass that has water filled up to 5 cm. If a small particle is floating on the surface of water, its image, as seen from directly above the glass, is at a distance d from the surface of water. The value of d is close to (Refractive index of water = 1.33)",["13.4 cm","11.7 cm","6.7 cm","8.8 cm"],3,"f = −20 cm and the particle is 5 cm in front of the mirror: {1;v} = {1;f} − {1;u} = −{1;20} + {1;5} = {3;20}, v = +6.67 cm behind the mirror.\nThe image is 5 + 6.67 = 11.67 cm below the water surface (in water terms).\nSeen from above: d = {11.67;1.33} ≈ 8.8 cm."),
M("JEE Main 2019 · 12 Apr · Shift 2","refr","Total internal reflection","A transparent cube of side d, made of a material of refractive index μ₂, is immersed in a liquid of refractive index μ₁ (μ₁ < μ₂). A ray is incident on the face AB at an angle θ. Total internal reflection takes place at point E on the face BC (adjacent to AB). Then θ must satisfy",["θ > sin⁻¹({μ₁;μ₂})","θ < sin⁻¹(√({μ₂²;μ₁²} − 1))","θ > sin⁻¹(√({μ₂²;μ₁²} − 1))","θ < sin⁻¹({μ₁;μ₂})"],1,"At AB: μ₁ sin θ = μ₂ sin r. At BC the incidence angle is 90° − r, and TIR needs μ₂ cos r ≥ μ₁.\nSo sin² r ≤ 1 − {μ₁²;μ₂²}, giving sin θ ≤ {μ₂;μ₁}√(1 − {μ₁²;μ₂²}) = √({μ₂²;μ₁²} − 1).\nθ < sin⁻¹√({μ₂²;μ₁²} − 1)."),
M("JEE Main 2017 · Online","refr","Total internal reflection","Let the refractive index of a denser medium with respect to a rarer medium be n₁₂ and its critical angle θ_C. At an angle of incidence A when light is travelling from denser medium to rarer, a part of the light is reflected and the rest is refracted and the angle between reflected and refracted rays is 90°. Angle A is given by",["{1;tan⁻¹(sin θ_C)}","{1;cos⁻¹(sin θ_C)}","tan⁻¹(sin θ_C)","cos⁻¹(sin θ_C)"],2,"With the 90° condition, refraction angle = 90° − A, so n₁₂ sin A = cos A, giving tan A = {1;n₁₂}.\nSince sin θ_C = {1;n₁₂}, A = tan⁻¹(sin θ_C)."),
M("JEE Main 2016 · Online","mirror","Mirror and water","A hemispherical glass body of radius 10 cm and refractive index 1.5 is silvered on its curved surface. A small air bubble is 6 cm below the flat surface inside it along the axis. The position of the image of the air bubble made by the mirror is seen",["14 cm below flat surface","20 cm below flat surface","16 cm below flat surface","30 cm below flat surface"],1,"The silvered curved surface is a concave mirror, f = −5 cm, with pole 10 cm below the flat surface. The bubble is 4 cm from the pole: u = −4.\n{1;v} = {1;f} − {1;u} = −{1;5} + {1;4} = {1;20}, v = 20 cm behind the mirror, which is 30 cm below the flat surface (inside glass).\nSeen from outside: {30;1.5} = 20 cm below the flat surface."),
M("JEE Main 2014","refr","Total internal reflection","A green light is incident from the water to the air-water interface at the critical angle (θ). Select the correct statement.",["The entire spectrum of visible light will come out of the water at various angles to the normal.","The entire spectrum of visible light will come out of the water at an angle of 90° to the normal.","The spectrum of visible light whose frequency is less than that of green light will come out to the air medium.","The spectrum of visible light whose frequency is more than that of green light will come out to the air medium."],2,"Lower frequency (towards red) means a smaller refractive index and so a larger critical angle than green's.\nFor those colours the incidence angle θ is below their critical angle, so they refract out. Higher frequencies (blue, violet) have smaller critical angles and are totally reflected."),
M("JEE Advanced 2014","refr","Total internal reflection","A point source S is placed at the bottom of a transparent block of height 10 mm and refractive index 2.72. It is immersed in a lower refractive index liquid as shown in the figure. It is found that the light emerging from the block to the liquid forms a circular bright spot of diameter 11.54 mm on the top of the block. The refractive index of the liquid is",["1.21","1.30","1.36","1.42"],2,"The spot radius is 5.77 mm = h tan θc with h = 10 mm, so tan θc = 0.577 and θc = 30°.\nsin θc = {n_liquid;2.72} gives n_liquid = 2.72 × {1;2} = 1.36."),
M("JEE Main 2013 · Online","refr","Total internal reflection","Light is incident from a medium into air at two possible angles of incidence (a) 20° and (b) 40°. In the medium light travels 3.0 cm in 0.2 ns. The ray will",["suffer total internal reflection in both cases (a) and (b)","suffer total internal reflection in case (b) only","have partial reflection and partial transmission in case (b)","have 100% transmission in case (a)."],1,"v = {3 × 10⁻²;0.2 × 10⁻⁹} = 1.5 × 10⁸ m/s, so n = 2 and sin θc = {1;2}: θc = 30°.\n20° < 30°: partial reflection and transmission. 40° > 30°: total internal reflection. Only (b) is right."),
M("AIEEE 2011","refr","Snell's law","Let the x-z plane be the boundary between two transparent media. Medium 1 in z ≥ 0 has a refractive index of √2 and medium 2 with z < 0 has a refractive index of √3. A ray of light in medium 1 given by the vector A⃗ = 6√3 î + 8√3 ĵ − 10 k̂ is incident on the plane of separation. The angle of refraction in medium 2 is",["30°","45°","60°","75°"],1,"|A⃗| = √(108 + 192 + 100) = 20. The normal is along z, so cos i = {10;20}, i = 60°.\n√2 sin 60° = √3 sin r gives sin r = {1;√2}, so r = 45°."),
M("AIEEE 2009","refr","Optical fibre","A transparent solid cylindrical rod has a refractive index of {2;√3}. It is surrounded by air. A light ray is incident at the mid-point of one end of the rod as shown in the figure. The incident angle θ for which the light ray grazes along the wall of the rod is",["sin⁻¹({1;2})","sin⁻¹({√3;2})","sin⁻¹({2;√3})","sin⁻¹({1;√3})"],3,"Grazing along the wall means the incidence at the wall equals θc: sin θc = {√3;2}, θc = 60°.\nSo the refraction angle at the end face is r = 90° − 60° = 30°.\nsin θ = n sin r = {2;√3} × {1;2} = {1;√3}."),
M("IIT-JEE 2009","refr","Apparent depth","A ball is dropped from a height of 20 m above the surface of water in a lake. The refractive index of water is 4/3. A fish inside the lake, in the line of fall of the ball, is looking at the ball. At an instant, when the ball is 12.8 m above the water surface, the fish sees the speed of ball as (Take g = 10 m/s²)",["9 m/s","12 m/s","16 m/s","21.33 m/s"],2,"Having fallen 20 − 12.8 = 7.2 m, the ball's speed is √(2 × 10 × 7.2) = 12 m/s.\nTo an observer in water, a height H in air appears as nH, so all speeds appear multiplied by n: {4;3} × 12 = 16 m/s."),
M("IIT-JEE 2008","refr","Snell's law","A light beam is travelling from Region I to Region IV (Refer figure; the interfaces are parallel). The refractive index in Regions I, II, III and IV are n₀, {n₀;2}, {n₀;6} and {n₀;8}, respectively. The angle of incidence θ for which the beam just misses entering Region IV is",["sin⁻¹({3;4})","sin⁻¹({1;8})","sin⁻¹({1;4})","sin⁻¹({1;3})"],1,"For parallel interfaces n sin θ is the same in every region. The beam just misses entering region IV when the angle there is 90°.\nn₀ sin θ = {n₀;8} × 1, so θ = sin⁻¹({1;8})."),
M("AIEEE 2005","refr","Total internal reflection","A fish looking up through the water sees the outside world contained in a circular horizon. If the refractive index of water is {4;3} and the fish is 12 cm below the surface, the radius of this circle (in cm) is",["36√5","4√5","36√7","{36;√7}"],3,"The circle has radius R = h tan θc, with sin θc = {3;4}, tan θc = {3;√7}.\nR = 12 × {3;√7} = {36;√7} cm."),
M("IIT-JEE 2005","mirror","Mirror and water","A container is filled with water (μ = 1.33) up to a height of 33.25 cm. A concave mirror is placed 15 cm above the water level and the image of an object placed at the bottom is formed 25 cm below the water level. Focal length of the mirror is",["15 cm","20 cm","−18.31 cm","10 cm"],2,"The object at the bottom (33.25 cm deep) appears at {33.25;1.33} = 25 cm below the surface, i.e. 15 + 25 = 40 cm from the mirror.\nThe image, 25 cm below the surface in the water, appears at {25;1.33} = 18.8 cm below the surface: 33.8 cm from the mirror.\n{1;f} = {1;40} + {1;33.8}, f ≈ 18.3 cm. For the concave mirror this is f = −18.31 cm in the Cartesian convention."),
M("AIEEE 2004","refr","Total internal reflection","A light ray is incident perpendicular to one face of a 90° prism and is totally internally reflected at the glass-air interface. If the angle of reflection is 45°, we conclude that the refractive index n",["n < {1;√2}","n > √2","n > {1;√2}","n < √2"],1,"The ray meets the hypotenuse at 45°, and TIR needs 45° ≥ θc, i.e. sin 45° ≥ {1;n}.\nSo n ≥ √2 (n > √2 for the ray to be totally reflected)."),
M("IIT-JEE 2004","refr","Refraction at a spherical surface","A point object is placed at the centre of a glass sphere of radius 6 cm and refractive index 1.5. The distance of virtual image from the surface is",["6 cm","4 cm","12 cm","9 cm"],0,"Every ray from the centre travels along a radius, so it meets the surface normally and is not deviated.\nThe image stays at the centre, 6 cm from the surface."),
M("IIT-JEE 2004","refr","Refractive index, speed and wavelength","A source emits sound of frequency 600 Hz inside water. The frequency heard in air will be equal to (velocity of sound in water = 1500 m/s, velocity of sound in air = 300 m/s)",["3000 Hz","120 Hz","600 Hz","6000 Hz"],2,"Frequency is set by the source and does not change on crossing into another medium. It stays 600 Hz (only the wavelength changes)."),
M("IIT-JEE 2004","refr","Total internal reflection","A beam of white light is incident on glass air interface from glass to air such that green light just suffers total internal reflection. The colours of the light which will come out are",["violet, indigo, blue","all colours except green","yellow, orange, red","white light."],2,"Colours with a smaller refractive index than green (yellow, orange, red) have a larger critical angle, so the incidence angle is below it and they come out.\nViolet, indigo and blue have smaller critical angles and are totally reflected."),
M("AIEEE 2003","refr","Snell's law","A ray of light is incident at the glass-water interface at an angle i. It emerges finally parallel to the surface of water. Then the value of μ_g would be",["({4;3}) sin i","{1;sin i}","{4;3}","1"],1,"The ray finally travels along the water-air surface, so its angle there is 90°.\nMultiplying Snell's law across both interfaces: μ_g sin i = μ_w sin r = 1 × sin 90°.\nSo μ_g = {1;sin i}."),
M("AIEEE 2002","refr","Optical fibre","Which of the following is used in optical fibres?",["Total internal reflection","Scattering","Diffraction","Refraction"],0,"Light is trapped in the core of an optical fibre by repeated total internal reflection at the core–cladding boundary."),
M("IIT-JEE 2002","refr","Apparent depth","An observer can see through a pin-hole the top end of a thin rod of height h, placed at the bottom against one wall of a beaker (see figure). The beaker height is 3h and its radius h; the pin-hole is at the top rim of the opposite wall. When the beaker is filled with a liquid up to a height 2h, he can see the lower end of the rod. Then the refractive index of the liquid is",["{5;2}","√({5;2})","√({3;2})","{3;2}"],1,"Without liquid, the line of sight from the pin-hole to the top of the rod falls 2h over a width 2h: 45°.\nWith liquid, this ray hits the surface 2h above the bottom, at a horizontal distance h from the rod's wall, so sin i = sin 45°. In the liquid it goes from there to the rod's lower end: tan r = {h;2h}, sin r = {1;√5}.\nn = {sin i;sin r} = {√5;√2} = √({5;2})."),
M("IIT-JEE 2001","refr","Snell's law","A ray of light passes through four transparent media with refractive indices μ₁, μ₂, μ₃ and μ₄ as shown in the figure. The surfaces of all media are parallel. If the emergent ray CD is parallel to the incident ray AB, we must have",["μ₁ = μ₂","μ₂ = μ₃","μ₃ = μ₄","μ₄ = μ₁"],3,"For parallel surfaces μ sin θ is the same in every medium: μ₁ sin θ₁ = μ₄ sin θ₄.\nThe emergent and incident rays are parallel, so θ₄ = θ₁ and μ₄ = μ₁."),
M("IIT-JEE 2000","refr","Lateral shift in a slab","A diverging beam of light from a point source S having divergence angle α, falls symmetrically on a glass slab as shown. The angles of incidence of the two extreme rays are equal. If the thickness of the glass slab is t and the refractive index μ, then the divergence angle of the emergent beam is",["zero","α","sin⁻¹({1;μ})","2 sin⁻¹({1;μ})"],1,"A parallel-sided slab only shifts each ray sideways; every emergent ray is parallel to its incident ray.\nSo the angle between the extreme rays is unchanged: α."),
M("IIT-JEE 2000","refr","Total internal reflection","A rectangular glass slab ABCD of refractive index μ₁ is immersed in water of refractive index μ₂ (μ₁ > μ₂). A ray of light is incident at the surface AB of the slab as shown in the figure. The maximum value of the angle α_max such that the ray comes out only from the other surface CD is given by",["sin⁻¹[{μ₁;μ₂} cos(sin⁻¹({μ₂;μ₁}))]","sin⁻¹[μ₁ cos(sin⁻¹({1;μ₂}))]","sin⁻¹({μ₁;μ₂})","sin⁻¹({μ₂;μ₁})"],0,"At AB: μ₂ sin α = μ₁ sin r. The ray reaches the top face AD at incidence 90° − r and must be totally reflected there: cos r ≥ {μ₂;μ₁}, so sin r ≤ cos(sin⁻¹({μ₂;μ₁})).\nTherefore sin α_max = {μ₁;μ₂} cos(sin⁻¹({μ₂;μ₁}))."),
M("IIT-JEE 1980","huyg","Frequency, speed and wavelength","When a ray of light enters a glass slab from air",["its wavelength decreases.","its wavelength increases.","its frequency increases.","neither its wavelength nor its frequency changes."],0,"The frequency stays the same, and the speed falls to c/n. Since λ = v/f, the wavelength decreases."),
M("JEE Advanced 2025","mirror","Mirror and slab","Two identical concave mirrors each of focal length f are facing each other as shown in the schematic diagram. The focal length f is much larger than the size of the mirrors. A glass slab of thickness t and refractive index n₀ is kept equidistant from the mirrors and perpendicular to their common principal axis. A monochromatic point light source S is embedded at the center of the slab on the principal axis, as shown in the schematic diagram. For the image to be formed on S itself, which of the following distances between the two mirrors is/are correct?",["4f + (1 − {1;n₀})t","2f + (1 − {1;n₀})t","4f + (n₀ − 1)t","2f + (n₀ − 1)t"],[0,1],"Seen from a mirror through half the slab, S appears {t;2n₀} from the slab face instead of {t;2}. If the mirrors are L apart, the effective object distance is u = {L;2} − {t;2}(1 − {1;n₀}).\nCase 1: rays strike a mirror normally (S at the centre of curvature): u = 2f, so L = 4f + (1 − {1;n₀})t.\nCase 2: S at the focus: u = f, so the beam is parallel between the mirrors and the second mirror brings it back to S: L = 2f + (1 − {1;n₀})t.\nSo (a) and (b)."),
M("JEE Advanced 2021","refr","Total internal reflection","A wide slab consisting of two media of refractive indices n₁ and n₂ is placed in air as shown in the figure (medium n₁ below, medium n₂ above it, air above n₂, all boundaries parallel). A ray of light is incident from medium n₁ to n₂ at an angle θ, where sin θ is slightly larger than {1;n₁}. Take refractive index of air as 1. Which of the following statement(s) is(are) correct?",["The light ray enters air if n₂ = n₁.","The light ray is finally reflected back into the medium of refractive index n₁ if n₂ < n₁.","The light ray is finally reflected back into the medium of refractive index n₁ if n₂ > n₁.","The light ray is reflected back into the medium of refractive index n₁ if n₂ = 1."],[1,2,3],"For parallel boundaries n sin θ is conserved: in the second medium n₂ sin θ₂ = n₁ sin θ > 1.\nIf the ray reaches the top, it meets air with n₂ sin θ₂ > 1, so it is totally reflected and comes back to n₁ (this covers n₂ < n₁ and n₂ > n₁). If n₂ = 1 the ray is already totally reflected at the n₁–n₂ boundary.\nIf n₂ = n₁ the ray meets air at incidence θ with n₁ sin θ > 1: it cannot enter air. So (b), (c), (d)."),
M("JEE Advanced 2020","refr","Apparent depth","A beaker of radius r is filled with water (refractive index {4;3}) up to a height H as shown in the figure on the left. The beaker is kept on a horizontal table rotating with angular speed ω. This makes the water surface curved so that the difference in the height of water level at the center and at the circumference of the beaker is h (h ≪ H, h ≪ r), as shown in the figure on the right. Take this surface to be approximately spherical with a radius of curvature R. Which of the following is/are correct? (g is the acceleration due to gravity)",["R = {h² + r²;2h}","R = {3r²;2h}","Apparent depth of the bottom of the beaker is close to {3H;2}(1 + {ω²H;2g})⁻¹.","Apparent depth of the bottom of the beaker is close to {3H;4}(1 + {ω²H;4g})⁻¹."],[0,3],"Chord half-width r and sagitta h on a sphere of radius R: R² = r² + (R − h)², so R = {r² + h²;2h}. Statement (a) is true; (b) is not.\nThe surface is the paraboloid z = {ω²r²;2g}, whose radius of curvature at the centre is R = {g;ω²}.\nWater to air at a concave-upward surface (centre of curvature in air, R positive): {1;v} − {4/3;−H} = {1 − 4/3;R}, so {1;|v|} = {4;3H} + {1;3R}.\n|v| = {3H;4}(1 + {H;4R})⁻¹ = {3H;4}(1 + {ω²H;4g})⁻¹. So (a) and (d)."),
M("JEE Advanced 2019","refr","Apparent depth","Three glass cylinders of equal height H = 30 cm and same refractive index n = 1.5 are placed on a horizontal surface as shown in figure. Cylinder I has a flat top, cylinder II has a convex top and cylinder III has a concave top. The radii of curvature of the two curved tops are same (R = 3 m). If H₁, H₂ and H₃ are the apparent depths of a point X on the bottom of the three cylinders, respectively, the correct statement(s) is/are",["H₂ > H₁","H₃ > H₁","0.8 cm < (H₂ − H₁) < 0.9 cm","H₂ > H₃"],[0,3],"Flat top: H₁ = {30;1.5} = 20 cm.\nConvex top (centre of curvature in glass, R = −300 cm): {1;v} − {1.5;−30} = {−0.5;−300}, so {1;v} = {1;600} − {1;20} = −{29;600}: H₂ = 20.69 cm.\nConcave top (R = +300 cm): {1;v} + {1;20} = −{1;600}, so {1;v} = −{31;600}: H₃ = 19.35 cm.\nSo H₂ > H₁ and H₂ > H₃; H₃ < H₁, and H₂ − H₁ = 0.69 cm, not in 0.8 to 0.9."),
M("JEE Advanced 2016","refr","Refraction through a graded slab","A transparent slab of thickness d has a refractive index n(z) that increases with z. Here z is the vertical distance inside the slab, measured from the top. The slab is placed between two media with uniform refractive indices n₁ and n₂ (> n₁), as shown in the figure. A ray of light is incident with angle θᵢ from medium 1 and emerges in medium 2 with refraction angle θ_f with a lateral displacement l. Which of the following statement(s) is (are) true?",["l is independent of n₂","n₁ sin θᵢ = n₂ sin θ_f","l is dependent on n(z)","n₁ sin θᵢ = (n₂ − n₁) sin θ_f"],[0,1,2],"At every parallel boundary n sin θ is conserved, so n₁ sin θᵢ = n(z) sin θ(z) = n₂ sin θ_f. Statement (b) is true and (d) is not.\nInside the slab sin θ(z) = {n₁ sin θᵢ;n(z)}, and l = ∫ tan θ(z) dz depends on the profile n(z) (c), not on the medium n₂ below it (a)."),
M("JEE Advanced 2015","refr","Refraction at a spherical surface","Two identical glass rods S₁ and S₂ (refractive index = 1.5) have one convex end of radius of curvature 10 cm. They are placed with the curved surfaces at a distance d as shown in the figure, with their axes (shown by the dashed line) aligned. When a point source of light P is placed inside rod S₁ on its axis at a distance of 50 cm from the curved face, the light rays emanating from it are found to be parallel to the axis inside S₂. The distance d is",["60 cm","70 cm","80 cm","90 cm"],1,"S₁ face (glass to air, R = −10 cm): {1;v} − {1.5;−50} = {1 − 1.5;−10}, so {1;v} = 0.05 − 0.03 = 0.02: v = 50 cm in air.\nThis image is the object for the face of S₂ (air to glass, R = +10 cm). Rays parallel inside S₂ means v = ∞: −{1;u} = {0.5;10}, so u = −20 cm.\nd = 50 + 20 = 70 cm."),
M("JEE Advanced 2014","refr","Refraction at a spherical surface","A transparent thin film of uniform thickness and refractive index n₁ = 1.4 is coated on the convex spherical surface of radius R at one end of a long solid glass cylinder of refractive index n₂ = 1.5, as shown in the figure. Rays of light parallel to the axis of the cylinder traversing through the film from air to glass get focused at distance f₁ from the film, while rays of light traversing from glass to air get focused at distance f₂ from the film. Then",["|f₁| = 3R","|f₁| = 2.8R","|f₂| = 2R","|f₂| = 1.4R"],[0,2],"A thin film of uniform thickness does not change the result, so treat it as a single air-glass surface.\nAir to glass: {1.5;f₁} = {1.5 − 1;R}, so |f₁| = 3R.\nGlass to air (R measured as −R): {1;f₂} = {1 − 1.5;−R}, so |f₂| = 2R."),
M("IIT-JEE 1998","refr","Refraction at a spherical surface","A spherical surface of radius of curvature R separates air (refractive index 1.0) from glass (refractive index 1.5). The centre of curvature is in the glass. A point object P placed in air is found to have a real image Q in the glass. The line PQ cuts the surface at a point O and PO = OQ. The distance PO is equal to",["5R","3R","2R","1.5R"],0,"Let PO = OQ = x. {1.5;x} − {1;−x} = {0.5;R}, so {2.5;x} = {0.5;R}.\nx = 5R."),
M("IIT-JEE 1998","refr","Total internal reflection","A ray of light travelling in a transparent medium falls on a surface separating the medium from air at an angle of incidence of 45°. The ray undergoes total internal reflection. If μ is the refractive index of the medium with respect to air, select the possible value(s) of μ from the following",["1.3","1.4","1.5","1.6"],[2,3],"TIR at 45° needs θc ≤ 45°, i.e. {1;μ} ≤ sin 45°, so μ ≥ √2 = 1.414.\nOnly 1.5 and 1.6 qualify (1.4 is just below √2)."),
N("JEE Main 2025 · 3 Apr · Shift 2","refr","Refraction at a spherical surface","Light from a point source in air falls on a spherical glass surface (refractive index, μ = 1.5 and radius of curvature = 50 cm). The image is formed at a distance of 200 cm from the glass surface inside the glass. The magnitude of distance of the light source from the glass surface is ______ m.",4,"{n₂;v} − {n₁;u} = {n₂ − n₁;R}: {1.5;200} − {1;u} = {0.5;50}.\n{1;u} = 0.0075 − 0.01 = −0.0025, so u = −400 cm = 4 m."),
N("JEE Main 2025 · 7 Apr · Shift 1","refr","Apparent depth","A container contains a liquid with refractive index of 1.2 up to a height of 60 cm and another liquid having refractive index 1.6 is added to height H above first liquid. If viewed from above, the apparent shift in the position of bottom of container is 40 cm. The value of H is ______ cm. (Consider liquids are immiscible)",80,"Each layer of thickness t shifts the bottom up by t(1 − {1;n}).\n60(1 − {1;1.2}) + H(1 − {1;1.6}) = 10 + 0.375H = 40, so H = 80 cm."),
N("JEE Main 2025 · 29 Jan · Shift 1","refr","Snell's law","Two light beams fall on a transparent material block at point 1 and 2 with angle θ₁ and θ₂, respectively, as shown in figure (θ₁ and θ₂ are the angles the beams make with the top surface). After refraction, the beams intersect at point 3 which is exactly on the interface at the other end of the block. Given: the distance between 1 and 2, d = 4√3 cm and θ₁ = θ₂ = cos⁻¹({n₂;2n₁}), where refractive index of the block n₂ > refractive index of the outside medium n₁, then the thickness of the block is ______ cm.",6,"The angle of incidence is 90° − θ, so sin i = cos θ = {n₂;2n₁}.\nn₁ sin i = n₂ sin r gives sin r = {1;2}, r = 30°.\nEach beam travels sideways {d;2} = 2√3 cm in the block: thickness = {2√3;tan 30°} = 6 cm."),
N("JEE Main 2024 · 4 Apr · Shift 2","refr","Lateral shift in a slab","A light ray is incident on a glass slab of thickness 4√3 cm and refractive index √2. The angle of incidence is equal to the critical angle for the glass slab with air. The lateral displacement of ray after passing through glass slab is ______ cm. (Given: sin 15° = 0.25)",2,"θc = sin⁻¹({1;√2}) = 45°, so i = 45°. sin r = {sin 45°;√2} = {1;2}, r = 30°.\nShift = {t sin(i − r);cos r} = {4√3 × 0.25;√3/2} = 2 cm."),
N("JEE Main 2024 · 27 Jan · Shift 1","refr","Apparent depth","Two immiscible liquids of refractive indices {8;5} and {3;2} respectively are put in a beaker as shown in the figure. The height of each column is 6 cm. A coin is placed at the bottom of the beaker. For near normal vision, the apparent depth of the coin is {α;4} cm. The value of α is ______.",31,"Apparent depth = {6;8/5} + {6;3/2} = 3.75 + 4 = 7.75 cm = {31;4} cm.\nSo α = 31."),
N("JEE Main 2023 · 6 Apr · Shift 1","refr","Snell's law","A pole is vertically submerged in swimming pool, such that it gives a length of shadow 2.15 m within water when sunlight is incident at an angle of 30° with the surface of water. If swimming pool is filled to a height of 1.5 m then the height of the pole above the water surface in centimeters is (n_w = {4;3}) ______.",50,"The angle of incidence is 60°: sin r = {sin 60°;4/3} = 0.650, tan r = 0.854.\nIn water the shadow spans 1.5 × 0.854 = 1.28 m horizontally, so the part from the pole above water is 2.15 − 1.28 = 0.87 m.\nIt equals h tan 60°: h = {0.87;1.732} = 0.50 m = 50 cm."),
N("JEE Main 2023 · 8 Apr · Shift 2","refr","Refraction at a spherical surface","Two transparent media having refractive indices 1.0 and 1.5 are separated by a spherical refracting surface of radius of curvature 30 cm. The centre of curvature of surface is towards denser medium and a point object is placed on the principle axis in rarer medium at a distance of 15 cm from the pole of the surface. The distance of image from the pole of the surface is ______ cm.",30,"{n₂;v} − {n₁;u} = {n₂ − n₁;R}: {1.5;v} + {1;15} = {0.5;30}.\n{1.5;v} = {1;60} − {4;60} = −{3;60}, so v = −30 cm: the image is 30 cm from the pole, on the object's side (virtual)."),
N("JEE Main 2023 · 11 Apr · Shift 2","refr","Apparent depth","As shown in the figure, a plane mirror is fixed at a height of 50 cm from the bottom of a tank containing water (μ = {4;3}). The height of water in the tank is 8 cm. A small bulb is placed at the bottom of the water tank. The distance of the image of the bulb formed by the mirror from the bottom of the tank is ______ cm.",98,"Seen from above, the bulb appears {8;4/3} = 6 cm below the water surface, i.e. 2 cm above the bottom.\nThe mirror is 50 − 2 = 48 cm from this apparent position, and a plane mirror puts the image 48 cm behind it.\nDistance from the bottom = 50 + 48 = 98 cm."),
N("JEE Main 2023 · 13 Apr · Shift 1","refr","Apparent depth","A fish rising vertically upward with a uniform velocity of 8 m s⁻¹, observe that a bird is diving vertically downward towards the fish with the velocity of 12 m s⁻¹. If the refractive index of water is {4;3}, then the actual velocity of the diving bird to pick the fish, will be ______ m s⁻¹.",3,"Take the bird's actual speed v. The fish sees the bird at n times its true height, and the fish's own rise also shortens the gap.\nApparent closing speed: n v + 8 = 12, so {4;3} v = 4 and v = 3 m s⁻¹."),
N("JEE Main 2023 · 25 Jan · Shift 1","refr","Lateral shift in a slab","A ray of light is incident from air on a glass plate having thickness √3 cm and refractive index √2. The angle of incidence of a ray is equal to the critical angle for glass-air interface. The lateral displacement of the ray when it passes through the plate is ______ × 10⁻² cm. (Given sin 15° = 0.26)",52,"i = θc = 45°, sin r = {sin 45°;√2} = {1;2}, r = 30°.\nShift = {t sin(i − r);cos r} = {√3 × 0.26;√3/2} = 0.52 cm = 52 × 10⁻² cm."),
N("JEE Main 2022 · 29 Jul · Shift 1","refr","Snell's law","The X-Y plane be taken as the boundary between two transparent media M₁ and M₂. M₁ in Z ≥ 0 has a refractive index of √2 and M₂ with Z < 0 has refractive index of √3. A ray of light travelling in M₁ along the direction given by the vector P⃗ = 4√3 î − 3√3 ĵ − 5k̂, is incident on the plane of separation. The value of difference between the angle of incident in M₁ and the angle of refraction in M₂ will be ______ degree.",15,"|P⃗| = √(48 + 27 + 25) = 10. The normal is along z: cos i = {5;10}, i = 60°.\n√2 sin 60° = √3 sin r gives sin r = {1;√2}, r = 45°.\nDifference = 60° − 45° = 15°."),
N("JEE Main 2022 · 24 Jun · Shift 2","refr","Lateral shift in a slab","A ray of light is incident at an angle of incidence 60° on the glass slab of refractive index √3. After refraction, the light ray emerges out from other parallel face and lateral shift between incident ray and emergent ray is 4√3 cm. The thickness of the glass slab is ______ cm.",12,"sin r = {sin 60°;√3} = {1;2}, r = 30°.\nShift = {t sin(i − r);cos r} = {t sin 30°;cos 30°} = {t;√3}.\n{t;√3} = 4√3 gives t = 12 cm."),
N("JEE Main 2022 · 26 Jun · Shift 2","refr","Total internal reflection","A small bulb is placed at the bottom of a tank containing water to a depth of √7 m. The refractive index of water is 4/3. The area of the surface of water through which light from the bulb can emerge out is xπ m². The value of x is ______.",9,"sin θc = {3;4}, tan θc = {3;√7}. The radius of the bright circle is R = h tan θc = √7 × {3;√7} = 3 m.\nArea = πR² = 9π m², so x = 9."),
N("JEE Main 2022 · 29 Jun · Shift 1","lens","Ball lens","A parallel beam of light is allowed to fall on a transparent spherical globe of diameter 30 cm and refractive index 1.5. The distance from the centre of the globe at which the beam of light can converge is ______ mm.",225,"For a ball of radius R and index n, the paraxial focus lies at {nR;2(n − 1)} from the centre.\n{1.5 × 15;2 × 0.5} = 22.5 cm = 225 mm."),
N("JEE Advanced 2022","refr","Snell's law","Consider a configuration of n identical units, each consisting of three layers. The first layer is a column of air of height h = {1;3} cm, and the second and third layers are of equal thickness d = {√3 − 1;2} cm, and refractive indices μ₁ = √({3;2}) and μ₂ = √3, respectively. A light source O is placed on the top of the first unit, as shown in the figure. A ray of light from O is incident on the second layer of the first unit at an angle of θ = 60° to the normal. For a specific value of n, the ray of light emerges from the bottom of the configuration at a distance l = {8;√3} cm, as shown in the figure. The value of n is ______.",4,"Sideways advance per unit: air h tan 60° = {1;√3} cm.\nLayer μ₁: sin r = {sin 60°;√(3/2)} = {1;√2}, r = 45°, advance d tan 45° = {√3 − 1;2}.\nLayer μ₂: sin r = {sin 60°;√3} = {1;2}, r = 30°, advance d tan 30° = {3 − √3;6}.\nSum per unit = {2;√3} cm. n × {2;√3} = {8;√3} gives n = 4."),
N("JEE Main 2021 · 17 Mar · Shift 2","refr","Refraction at a spherical surface","The image of an object placed in air formed by a convex refracting surface, is at a distance of 10 m behind the surface. The image is real and is at {2;3} of the distance of the object from the surface. The wavelength of light inside the surface is 2/3 times the wavelength in air. The radius of the curved surface is {x;13} m. The value of x is ______.",30,"λ in the medium is {2;3} of λ in air, so n = {3;2}.\nv = 10 m and |u| = 15 m. {1.5;10} + {1;15} = {0.5;R}: 0.2167 = {0.5;R}.\nR = {30;13} m, so x = 30."),
N("JEE Main 2020 · 2 Sep · Shift 2","refr","Snell's law","A light ray enters a solid glass sphere of refractive index μ = √3 at an angle of incidence 60°. The ray is both reflected and refracted at the farther surface of the sphere. The angle (in degrees) between the reflected and refracted rays at this surface is ______.",90,"At the first surface sin r = {sin 60°;√3} = {1;2}, r = 30°. By symmetry the ray meets the far surface at 30° inside.\nThere it emerges at sin e = √3 sin 30°, e = 60°, while the reflected ray also makes 30° with the normal.\nThe angle between them is 180° − 30° − 60° = 90°."),
N("JEE Main 2020 · 3 Sep · Shift 1","refr","Apparent depth","An observer can see through a small hole on the side of a jar (radius 15 cm) at a point at height of 15 cm from the bottom (see figure). The hole is at a height of 45 cm. When the jar is filled with a liquid up to a height of 30 cm, the same observer can see the edge at the bottom of the jar. If the refractive index of the liquid is N/100, where N is an integer, the value of N is ______.",158,"Without liquid the line of sight falls 30 cm over the jar's 30 cm width: 45° to the vertical.\nIt meets the liquid surface (15 cm lower than the hole) 15 cm across. Inside, it must reach the bottom edge: 15 cm across and 30 cm down, so tan r = {1;2}, sin r = {1;√5}.\nn = {sin 45°;sin r} = √({5;2}) = 1.58, so N = 158."),
];
})();
